<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class TestingRequest extends Model { protected $fillable=['request_number','applicant_id','testing_service_id','assigned_lab_staff_id','status','sample_description','purpose','notes','submitted_at','completed_at']; protected $casts=['submitted_at'=>'datetime','completed_at'=>'datetime']; public function applicant(){return $this->belongsTo(User::class,'applicant_id');} public function service(){return $this->belongsTo(TestingService::class,'testing_service_id');} public function assignedStaff(){return $this->belongsTo(User::class,'assigned_lab_staff_id');} public function samples(){return $this->hasMany(TestingSample::class);} public function histories(){return $this->hasMany(TestingHistory::class)->orderBy('created_at');} public function result(){return $this->hasOne(TestingResult::class);} }
